it('fails gracefully on timeout', async () => {
  const slowServer = Bun.serve({
    port: 0,
    async fetch() {
      await new Promise(r => setTimeout(r, 20000));
      return new Response('OK', { status: 200 });
    },
  });
  const proc = Bun.spawn(['bun', 'PAI/Tools/AgentZero.ts', 'health'], {
    env: { ...process.env, HOME: tempDir, A0_BASE_URL: `http://localhost:${slowServer.port}` },
  });
  await proc.exited;
  expect(proc.exitCode).toBe(1);
  slowServer.stop();
});

it('fails with error for invalid command', async () => {
  const proc = Bun.spawn(['bun', 'PAI/Tools/AgentZero.ts', 'invalid-command'], {
    env: { ...process.env, HOME: tempDir },
  });
  const stderr = await new Response(proc.stderr).text();
  await proc.exited;
  expect(proc.exitCode).toBe(1);
  expect(stderr).toContain('Unknown command');
});

describe('Argument validation', () => {
  it('rejects invalid lifetime_hours values', async () => {
    const proc = Bun.spawn(['bun', 'PAI/Tools/AgentZero.ts', 'message', 'test', '--lifetime', '-1']);
    await proc.exited;
    expect(proc.exitCode).toBe(1);
  });
});

